<template><div><div class="admin-page-head"><div><h1>Бронирования</h1><p>Полная операционная история заказов Trove.</p></div></div><div class="filters"><input v-model="search" class="input" placeholder="ID, тур, направление, email…" @keyup.enter="load"><select v-model="status" class="select"><option value="">Все статусы</option><option value="pending">Pending</option><option value="confirmed">Confirmed</option><option value="provider_booking">Provider booking</option><option value="cancelled">Cancelled</option><option value="failed">Failed</option></select><button class="btn primary" @click="load">Найти</button></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Бронь</th><th>Клиент</th><th>Направление</th><th>Дата</th><th>Сумма</th><th>Статус</th><th>Оплата</th></tr></thead><tbody><tr v-for="b in data.items" :key="b.id"><td><NuxtLink class="admin-link" :to="`/admin/bookings/${b.id}`"><b>{{ b.id }}</b></NuxtLink><div class="muted">{{ b.title }}</div></td><td>{{ b.first_name }} {{ b.last_name||'' }}<div class="muted">{{ b.email }}</div></td><td>{{ b.destination }}</td><td>{{ date(b.departure_date) }}</td><td><b>{{ money(b.price) }}</b></td><td><span class="pill" :class="{success:b.status==='confirmed',warn:b.status==='pending'}">{{ b.status }}</span></td><td>{{ b.payment_status }}</td></tr></tbody></table><div v-if="!data.items.length" class="empty">Бронирований нет.</div></div></div></template>
<script setup lang="ts">definePageMeta({layout:'admin',middleware:'admin'});const api=useApi();const search=ref('');const status=ref('');const data=ref<any>({items:[]});const load=async()=>{data.value=await api('/api/admin/bookings',{query:{search:search.value,status:status.value,limit:50}})};await load();const money=(v:number)=>new Intl.NumberFormat('ru-RU').format(v||0)+' ₽';const date=(v:string)=>new Date(v).toLocaleDateString('ru-RU')</script>
